-- 1.1. Khoa / Bộ môn mặc định (departments) nếu chưa có
CREATE TABLE IF NOT EXISTS `departments` (
  `id` CHAR(36) NOT NULL,
  `code` VARCHAR(50) NULL,
  `name` VARCHAR(255) NULL,
  `description` TEXT NULL,
  `created_at` DATETIME NULL,
  `updated_at` DATETIME NULL,
  `deleted_at` DATETIME NULL,
  `is_active` TINYINT(1) NULL DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT '11111111-1111-1111-1111-111111111111', 'CNTT', 'Khoa Công nghệ thông tin', 1
WHERE NOT EXISTS (SELECT 1 FROM `departments` WHERE `id` = '11111111-1111-1111-1111-111111111111');

-- 1.2. Bảng ngành đào tạo (majors)
CREATE TABLE IF NOT EXISTS `majors` (
  `id` CHAR(36) NOT NULL,
  `department_id` CHAR(36) NULL,
  `code` VARCHAR(100) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `description` TEXT NULL,
  `effective_date` DATE NULL,
  `expiry_date` DATE NULL,
  `created_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NULL,
  `created_by` CHAR(36) NULL,
  `updated_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  `deleted_by` CHAR(36) NULL,
  `is_active` TINYINT(1) NULL DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT s.id, s.department_id, s.code, s.name, NOW(), 1 FROM (
  SELECT '22222222-0000-0000-0000-000000000001' AS id, '11111111-1111-1111-1111-111111111111' AS department_id, 'CNTT' AS code, 'Công nghệ thông tin' AS name
  UNION ALL SELECT '22222222-0000-0000-0000-000000000002', '11111111-1111-1111-1111-111111111111', 'KTPM', 'Kỹ thuật phần mềm'
  UNION ALL SELECT '22222222-0000-0000-0000-000000000003', '11111111-1111-1111-1111-111111111111', 'HTTT', 'Hệ thống thông tin'
  UNION ALL SELECT '22222222-0000-0000-0000-000000000004', '11111111-1111-1111-1111-111111111111', 'QTKD', 'Quản trị kinh doanh'
  UNION ALL SELECT '22222222-0000-0000-0000-000000000005', '11111111-1111-1111-1111-111111111111', 'TCNH', 'Tài chính - Ngân hàng'
  UNION ALL SELECT '22222222-0000-0000-0000-000000000006', '11111111-1111-1111-1111-111111111111', 'NNA', 'Ngôn ngữ Anh'
) AS s WHERE NOT EXISTS (SELECT 1 FROM `majors` WHERE `code` = s.code);

-- 1.3. Bảng môn học / học phần (courses)
CREATE TABLE IF NOT EXISTS `courses` (
  `id` CHAR(36) NOT NULL,
  `department_id` CHAR(36) NULL,
  `code` VARCHAR(100) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `name_en` VARCHAR(255) NULL,
  `credits` DECIMAL(5,1) NULL DEFAULT 3.0,
  `cource_type` VARCHAR(255) NULL,
  `theory_hours` DECIMAL(5,1) NULL DEFAULT 30.0,
  `practice_hours` DECIMAL(5,1) NULL DEFAULT 30.0,
  `self_study_hours` DECIMAL(5,1) NULL,
  `internship_credits` DECIMAL(5,1) NULL,
  `description` TEXT NULL,
  `created_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NULL,
  `created_by` CHAR(36) NULL,
  `updated_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  `deleted_by` CHAR(36) NULL,
  `is_active` TINYINT(1) NULL DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT UUID(), s.code, s.name, s.name_en, s.credits, s.theory_hours, s.practice_hours, s.cource_type, s.department_id, NOW(), 1 FROM (
  SELECT 'THDC' AS code, 'Tin học đại cương' AS name, 'General Informatics' AS name_en, 3.0 AS credits, 30.0 AS theory_hours, 30.0 AS practice_hours, 'Bắt buộc' AS cource_type, '11111111-1111-1111-1111-111111111111' AS department_id
  UNION ALL SELECT 'LTNC', 'Lập trình nâng cao', 'Advanced Programming', 3.0, 30.0, 30.0, 'Bắt buộc', '11111111-1111-1111-1111-111111111111'
  UNION ALL SELECT 'WEB1', 'Lập trình Web 1', 'Web Programming 1', 3.0, 30.0, 30.0, 'Bắt buộc', '11111111-1111-1111-1111-111111111111'
  UNION ALL SELECT 'WEB2', 'Lập trình Web 2', 'Web Programming 2', 3.0, 30.0, 30.0, 'Bắt buộc', '11111111-1111-1111-1111-111111111111'
  UNION ALL SELECT 'CTDL', 'Cấu trúc dữ liệu và giải thuật', 'Data Structures and Algorithms', 3.0, 30.0, 30.0, 'Bắt buộc', '11111111-1111-1111-1111-111111111111'
  UNION ALL SELECT 'CSDL', 'Cơ sở dữ liệu', 'Database Systems', 3.0, 30.0, 30.0, 'Bắt buộc', '11111111-1111-1111-1111-111111111111'
) AS s WHERE NOT EXISTS (SELECT 1 FROM `courses` WHERE `code` = s.code);

