  `is_active` TINYINT(1) NULL DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Đồng bộ kiểu dữ liệu admission_year thành INT để khớp entity TrainingProgram của Nhóm 4
ALTER TABLE `training_programs` MODIFY COLUMN `admission_year` INT NULL;
UPDATE `training_programs` SET `admission_year` = 2026 WHERE `admission_year` IS NULL;

-- Thêm mẫu 6 chương trình đào tạo của Nhóm 4
