  SELECT 'IT_2023' AS code, 'Công nghệ thông tin' AS name, 'Information Technology' AS name_en, '22222222-0000-0000-0000-000000000001' AS major_id, '11111111-1111-1111-1111-111111111111' AS department_id, 'Đại học' AS degree_level, 'Chính quy' AS education_type, 150.0 AS total_credits, 120.0 AS required_credits, 20.0 AS elective_credits, 5.0 AS internship_credits, 5.0 AS thesis_credits, 2023 AS admission_year, 4.5 AS duration_years, 6.5 AS max_duration_years, '2023-09-05' AS effective_date, '2028-09-05' AS expiry_date, 'Chương trình Công nghệ thông tin' AS description, 'Đào tạo kỹ sư phần mềm' AS objectives, 'Lập trình full-stack' AS learning_outcomes, 'v1.0' AS version, 'Đang đào tạo' AS status
