  UNION ALL SELECT 'IS_2023', 'Hệ thống thông tin', 'Information Systems', '22222222-0000-0000-0000-000000000003', '11111111-1111-1111-1111-111111111111', 'Đại học', 'Chính quy', 148.0, 118.0, 20.0, 5.0, 5.0, 2023, 4.0, 6.0, '2023-09-05', '2027-09-05', 'Chương trình Hệ thống thông tin', 'Đào tạo phân tích dữ liệu', 'Thiết kế CSDL', 'v1.0', 'Đang đào tạo'
  UNION ALL SELECT 'BA_2023', 'Quản trị kinh doanh', 'Business Administration', '22222222-0000-0000-0000-000000000004', '11111111-1111-1111-1111-111111111111', 'Đại học', 'Chính quy', 135.0, 105.0, 20.0, 5.0, 5.0, 2023, 4.0, 6.0, '2023-09-05', '2027-09-05', 'Chương trình Quản trị kinh doanh', 'Cung cấp kiến thức quản trị', 'Có tư duy chiến lược', 'v1.0', 'Đang đào tạo'
  UNION ALL SELECT 'FB_2023', 'Tài chính - Ngân hàng', 'Finance and Banking', '22222222-0000-0000-0000-000000000005', '11111111-1111-1111-1111-111111111111', 'Đại học', 'Chính quy', 138.0, 108.0, 20.0, 5.0, 5.0, 2023, 4.0, 6.0, '2023-09-05', '2027-09-05', 'Chương trình Tài chính - Ngân hàng', 'Đào tạo quản trị tài chính', 'Phân tích tài chính', 'v1.0', 'Đang đào tạo'
  UNION ALL SELECT 'EL_2023', 'Ngôn ngữ Anh', 'English Language', '22222222-0000-0000-0000-000000000006', '11111111-1111-1111-1111-111111111111', 'Đại học', 'Chính quy', 130.0, 100.0, 20.0, 5.0, 5.0, 2023, 4.0, 6.0, '2023-09-05', '2027-09-05', 'Chương trình Ngôn ngữ Anh', 'Đào tạo tiếng Anh thương mại', 'Biên phiên dịch chuyên nghiệp', 'v1.0', 'Đang đào tạo'
