-- 1.5. Bảng môn học tiên quyết (course_prerequisites) - hỗ trợ cả mô hình ID và Code
CREATE TABLE IF NOT EXISTS `course_prerequisites` (
  `id` CHAR(36) NOT NULL,
  `course_id` CHAR(36) NULL,
  `prerequisite_course_id` CHAR(36) NULL,
  `course_code` VARCHAR(50) NULL,
  `course_name` VARCHAR(200) NULL,
  `prerequisite_code` VARCHAR(50) NULL,
  `prerequisite_name` VARCHAR(200) NULL,
  `description` VARCHAR(500) NULL,
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NULL,
  `created_by` CHAR(36) NULL,
  `updated_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  `deleted_by` CHAR(36) NULL,
  `is_active` TINYINT(1) NULL DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Bổ sung các cột nếu bảng đã tồn tại từ trước
SET @dbname = DATABASE();
SET @tablename = 'course_prerequisites';
SET @preparedStatement = (SELECT IF(
  (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = @dbname AND TABLE_NAME = @tablename AND COLUMN_NAME = 'course_code') > 0,
  'SELECT 1',
  'ALTER TABLE `course_prerequisites` ADD COLUMN `course_code` VARCHAR(50) NULL, ADD COLUMN `course_name` VARCHAR(200) NULL, ADD COLUMN `prerequisite_code` VARCHAR(50) NULL, ADD COLUMN `prerequisite_name` VARCHAR(200) NULL, ADD COLUMN `description` VARCHAR(500) NULL, ADD COLUMN `active` TINYINT(1) NOT NULL DEFAULT 1;'
));
PREPARE stmt FROM @preparedStatement;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- Seed dữ liệu môn tiên quyết mẫu
SELECT UUID(), s.course_code, s.course_name, s.prerequisite_code, s.prerequisite_name, s.description, 1, 1, NOW() FROM (
  SELECT 'CTDL' AS course_code, 'Cấu trúc dữ liệu và giải thuật' AS course_name, 'LTNC' AS prerequisite_code, 'Lập trình nâng cao' AS prerequisite_name, 'Cần hoàn thành Lập trình nâng cao' AS description
  UNION ALL SELECT 'CSDL', 'Cơ sở dữ liệu', 'THDC', 'Tin học đại cương', 'Môn nền tảng'
  UNION ALL SELECT 'WEB2', 'Lập trình Web 2', 'WEB1', 'Lập trình Web 1', 'Học Web 1 trước Web 2'
) AS s WHERE NOT EXISTS (SELECT 1 FROM `course_prerequisites` WHERE `course_code` = s.course_code AND `prerequisite_code` = s.prerequisite_code);


-- ====================================================================================================
-- PHẦN II. CẬP NHẬT & TÍCH HỢP CƠ SỞ DỮ LIỆU NHÓM 6 (ĐĂNG KÝ HỌC PHẦN)
-- ====================================================================================================

-- 2.1. Đợt đăng ký học phần (registration_periods): thêm cờ is_open
CREATE TABLE IF NOT EXISTS `registration_periods` (
  `id` CHAR(36) NOT NULL,
  `name` VARCHAR(200) NULL,
  `semester_id` CHAR(36) NULL,
  `start_time` DATETIME NULL,
  `end_time` DATETIME NULL,
  `target_config` TEXT NULL,
  `max_credits` SMALLINT NULL DEFAULT 25,
  `min_credits` SMALLINT NULL DEFAULT 12,
  `allow_retake` TINYINT(1) NULL DEFAULT 1,
  `is_open` TINYINT(1) NOT NULL DEFAULT 1,
  `is_active` TINYINT(1) NULL DEFAULT 1,
  `created_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NULL,
  `created_by` CHAR(36) NULL,
  `updated_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  `deleted_by` CHAR(36) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET @tablename = 'registration_periods';
SET @preparedStatement = (SELECT IF(
  (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = @dbname AND TABLE_NAME = @tablename AND COLUMN_NAME = 'is_open') > 0,
  'SELECT 1',
  'ALTER TABLE `registration_periods` ADD COLUMN `is_open` TINYINT(1) NOT NULL DEFAULT 1;'
));
PREPARE stmt FROM @preparedStatement;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- 2.2. Bảng lớp học phần đăng ký học lại / học cải thiện (ecourse_sections)
CREATE TABLE IF NOT EXISTS `ecourse_sections` (
  `id` CHAR(36) NOT NULL,
  `course_id` CHAR(36) NOT NULL,
  `semester_id` CHAR(36) NOT NULL,
  `code` VARCHAR(50) NOT NULL,
  `course_code` VARCHAR(100) NOT NULL,
  `course_name` VARCHAR(255) NOT NULL,
  `credits` INT NOT NULL,
  `max_capacity` INT NOT NULL,
  `current_enrolled` INT NOT NULL DEFAULT 0,
  `status` INT NOT NULL DEFAULT 1 COMMENT '1: Đang mở, 2: Đã khóa, 3: Đã hủy',
  `row_version` BIGINT NOT NULL DEFAULT 0,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` DATETIME(6) NULL,
  `deleted_at` DATETIME(6) NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ecourse_sections_semester_code` (`semester_id`, `code`),
  CONSTRAINT `ck_ecourse_sections_capacity` CHECK (`max_capacity` > 0 AND `current_enrolled` >= 0 AND `current_enrolled` <= `max_capacity`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2.3. Bảng phân quyền sinh viên theo đợt đăng ký (list_students)
CREATE TABLE IF NOT EXISTS `list_students` (
  `id` CHAR(36) NOT NULL,
  `registration_period_id` CHAR(36) NOT NULL,
  `student_id` CHAR(36) NOT NULL,
  `max_allowed_credits` INT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `deleted_at` DATETIME(6) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_list_students_period` (`registration_period_id`),
  KEY `ix_list_students_student` (`student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2.4. Bảng phân công cố vấn / quản lý sinh viên (manager_students)
CREATE TABLE IF NOT EXISTS `manager_students` (
  `id` CHAR(36) NOT NULL,
  `student_id` CHAR(36) NOT NULL,
  `manager_id` CHAR(36) NOT NULL COMMENT 'Liên kết sang bảng employees',
  `role_type` INT NOT NULL COMMENT '1: Cố vấn học tập, 2: Quản lý khoa',
  `is_primary` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `deleted_at` DATETIME(6) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_manager_students_student` (`student_id`),
  KEY `ix_manager_students_manager` (`manager_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2.5. Bảng môn học tương đương (course_equivalences)
CREATE TABLE IF NOT EXISTS `course_equivalences` (
  `id` CHAR(36) NOT NULL,
  `original_course_id` CHAR(36) NOT NULL,
  `equivalent_course_id` CHAR(36) NOT NULL,
  `equivalence_type` INT DEFAULT 1 COMMENT '1: Tương đương 1-1, 2: Môn thay thế',
  `effect_date` DATE NULL,
  `is_active` TINYINT(1) DEFAULT 1,
  `note` VARCHAR(500) NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` DATETIME(6) NULL,
  `deleted_at` DATETIME(6) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2.6. Cập nhật bảng course_registrations để liên kết với ecourse_sections
CREATE TABLE IF NOT EXISTS `course_registrations` (
  `id` CHAR(36) NOT NULL,
  `student_id` CHAR(36) NOT NULL,
  `course_class_id` CHAR(36) NULL,
  `ecourse_section_id` CHAR(36) NULL,
  `registration_period_id` CHAR(36) NULL,
  `registration_type` INT NULL DEFAULT 1,
  `replaced_grade_id` CHAR(36) NULL,
  `registered_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  `status` INT NOT NULL DEFAULT 1,
  `is_paid` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NULL,
  `created_by` CHAR(36) NULL,
  `updated_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  `deleted_by` CHAR(36) NULL,
  `is_active` TINYINT(1) NULL DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET @tablename = 'course_registrations';
SET @preparedStatement = (SELECT IF(
  (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = @dbname AND TABLE_NAME = @tablename AND COLUMN_NAME = 'ecourse_section_id') > 0,
  'SELECT 1',
  'ALTER TABLE `course_registrations` ADD COLUMN `ecourse_section_id` CHAR(36) NULL;'
));
PREPARE stmt FROM @preparedStatement;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- 2.7. Chuẩn hóa tên tiếng Việt cho học kỳ (semesters)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `school_year_name` = VALUES(`school_year_name`), `start_date` = VALUES(`start_date`), `end_date` = VALUES(`end_date`);

-- Dữ liệu mẫu lớp học lại của Nhóm 6
SELECT '66666666-0000-0000-0000-000000000001', c.id, 'e8765906-7f86-4caf-a819-e1b1ef10dc17', 'LTNC-20241-HL01', 'LTNC', 'Lập trình nâng cao', 3, 50, 0, 1, NOW()
