-- Đồng bộ code = room_code và name = room_name
UPDATE `rooms` SET `code` = COALESCE(`code`, `room_code`), `name` = COALESCE(`name`, `room_name`), `type` = COALESCE(`type`, `room_type`) WHERE `code` IS NULL OR `name` IS NULL;

