ON DUPLICATE KEY UPDATE `slot_code` = VALUES(`slot_code`), `start_time` = VALUES(`start_time`), `end_time` = VALUES(`end_time`);

-- 3.5. Bảng lịch học / thời khóa biểu (schedules)
CREATE TABLE IF NOT EXISTS `schedules` (
