-- ====================================================================================================
-- PHẦN IV. TẠO CÁC VIEW TÍCH HỢP LIÊN THÔNG (NHÓM 4 + NHÓM 6 + NHÓM 7)
-- ====================================================================================================

-- 4.1. View tra cứu môn học và môn tiên quyết (Nhóm 4)
CREATE OR REPLACE VIEW `v_course_prerequisites_details` AS
SELECT 
    cp.id AS prerequisite_id,
    cp.course_code,
    COALESCE(c.name, cp.course_name) AS course_name,
    cp.prerequisite_code,
    COALESCE(pc.name, cp.prerequisite_name) AS prerequisite_name,
    cp.description,
    cp.active
FROM `course_prerequisites` cp
LEFT JOIN `courses` c ON c.code = cp.course_code
LEFT JOIN `courses` pc ON pc.code = cp.prerequisite_code;

-- 4.2. View tổng quan các lớp mở đăng ký học lại và sĩ số (Nhóm 6 + Nhóm 4)
CREATE OR REPLACE VIEW `v_ecourse_sections_registration_overview` AS
SELECT 
    es.id AS ecourse_section_id,
    es.code AS section_code,
    es.course_code,
    es.course_name,
    es.credits,
    s.name AS semester_name,
    es.max_capacity,
    es.current_enrolled,
    (es.max_capacity - es.current_enrolled) AS remaining_slots,
    CASE 
        WHEN es.status = 1 THEN 'Đang mở đăng ký'
        WHEN es.status = 2 THEN 'Đã khóa'
        ELSE 'Đã hủy'
    END AS status_text,
    es.created_at
FROM `ecourse_sections` es
LEFT JOIN `semesters` s ON s.id = es.semester_id;

-- 4.3. View chi tiết thời khóa biểu kèm thông tin phòng học, lớp học phần, giảng viên (Nhóm 7)
CREATE OR REPLACE VIEW `v_schedule_detailed_overview` AS
SELECT 
    sc.id AS schedule_id,
    sc.day_of_week,
    sc.date AS schedule_date,
    sc.shift,
    sc.start_period,
    sc.end_period,
    sc.number_of_periods,
    COALESCE(r.name, r.room_name, r.code) AS room_name,
    b.name AS building_name,
    COALESCE(cs.name, sc.description) AS course_name,
    e.full_name AS lecturer_name,
    sc.mode,
    sc.schedule_status,
    sc.is_active
FROM `schedules` sc
LEFT JOIN `rooms` r ON r.id = sc.room_id
LEFT JOIN `buildings` b ON b.id = r.building_id
LEFT JOIN `course_sections` cs ON cs.id = sc.course_section_id
LEFT JOIN `employees` e ON e.id = sc.employee_id;

-- ====================================================================================================
-- PHẦN IV. TÍCH HỢP CƠ SỞ DỮ LIỆU NHÓM 3 (NHÂN SỰ - LƯƠNG - KHỐI LƯỢNG GIẢNG DẠY)
-- ====================================================================================================

-- 4.1. Bảng lương (payrolls) - chuyển từ PostgreSQL/Supabase sang MariaDB
CREATE TABLE IF NOT EXISTS `payrolls` (
  `id` CHAR(36) NOT NULL,
  `employee_id` CHAR(36) NOT NULL,
  `month` INT NOT NULL,
  `year` INT NOT NULL,
  `base_salary` DECIMAL(14,2) NOT NULL DEFAULT 2340000.00,
  `salary_coefficient` DECIMAL(6,2) NOT NULL,
  `basic_salary` DECIMAL(14,2) NOT NULL,
  `position_allowance` DECIMAL(14,2) NULL DEFAULT 0.00,
  `degree_allowance` DECIMAL(14,2) NULL DEFAULT 0.00,
  `bonus_allowance` DECIMAL(14,2) NULL DEFAULT 0.00,
  `insurance_deduction` DECIMAL(14,2) NULL DEFAULT 0.00,
  `net_salary` DECIMAL(14,2) NOT NULL,
  `status` VARCHAR(50) NULL DEFAULT 'PAID',
  `note` VARCHAR(255) NULL,
  `payment_date` DATE NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` VARCHAR(50) NULL,
  `updated_at` DATETIME NULL,
  `updated_by` VARCHAR(50) NULL,
  `deleted_at` DATETIME NULL,
  `deleted_by` VARCHAR(50) NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_employee_month_year` (`employee_id`, `month`, `year`),
  KEY `idx_payrolls_employee` (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bảng lương nhóm 3 (chuyển từ PostgreSQL)';

-- 4.2. Khối lượng giảng dạy (teaching_workloads) - chuyển từ PostgreSQL/Supabase sang MariaDB
CREATE TABLE IF NOT EXISTS `teaching_workloads` (
  `id` CHAR(36) NOT NULL,
  `employee_id` CHAR(36) NOT NULL,
  `academic_year` VARCHAR(20) NOT NULL DEFAULT '2026-2027',
