  `standard_quota` INT NOT NULL DEFAULT 280,
  `theory_hours` INT NOT NULL DEFAULT 0,
  `practice_hours` INT NOT NULL DEFAULT 0,
  `project_hours` INT NOT NULL DEFAULT 0,
  `total_hours` INT NOT NULL DEFAULT 0,
  `excess_hours` INT NOT NULL DEFAULT 0,
  `overtime_rate` DECIMAL(15,2) NOT NULL DEFAULT 120000.00,
  `overtime_pay` DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  `status` VARCHAR(50) NOT NULL DEFAULT 'COMPLETED',
  `notes` TEXT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` VARCHAR(50) NULL,
  `updated_at` DATETIME NULL,
  `updated_by` VARCHAR(50) NULL,
  `deleted_at` DATETIME NULL,
  `deleted_by` VARCHAR(50) NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_employee_year_sem` (`employee_id`, `academic_year`, `semester`),
  KEY `idx_tw_employee` (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Khối lượng giảng dạy nhóm 3 (chuyển từ PostgreSQL)';

-- ====================================================================================================
-- PHẦN V. TÍCH HỢP CƠ SỞ DỮ LIỆU NHÓM 11 (QUẢN LÝ TỐT NGHIỆP)
-- Chuyển từ SQL Server (dbo) sang MariaDB: UNIQUEIDENTIFIER -> CHAR(36), NVARCHAR -> VARCHAR,
-- DATETIME2 -> DATETIME, BIT -> TINYINT(1), TINYINT(result/classification) -> SMALLINT
-- ====================================================================================================

-- 5.1. Tiêu chí điều kiện tốt nghiệp (graduation_conditions)
CREATE TABLE IF NOT EXISTS `graduation_conditions` (
  `id` CHAR(36) NOT NULL,
  `program_id` CHAR(36) NOT NULL,
  `applied_cohort` VARCHAR(10) NOT NULL,
  `min_total_credits` INT NOT NULL,
  `min_gpa` DECIMAL(3,2) NOT NULL,
  `max_failed_credits` INT NOT NULL,
  `english_requirement` VARCHAR(255) NULL,
  `it_requirement` VARCHAR(255) NULL,
  `conduct_required` VARCHAR(255) NULL,
  `note` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NULL,
  `created_by` CHAR(36) NULL,
  `updated_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  `deleted_by` CHAR(36) NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Điều kiện tốt nghiệp nhóm 11';

-- 5.2. Đợt xét tốt nghiệp (graduation_sessions)
CREATE TABLE IF NOT EXISTS `graduation_sessions` (
  `id` CHAR(36) NOT NULL,
  `session_code` VARCHAR(50) NOT NULL,
  `session_name` VARCHAR(255) NOT NULL,
  `academic_year` VARCHAR(20) NULL,
  `semester` INT NULL,
  `start_date` DATE NULL,
  `due_date` DATE NULL,
  `description` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NULL,
  `created_by` CHAR(36) NULL,
  `updated_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  `deleted_by` CHAR(36) NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_graduation_sessions_code` (`session_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Đợt xét tốt nghiệp nhóm 11';

-- 5.3. Kết quả xét tốt nghiệp (graduation_results)
CREATE TABLE IF NOT EXISTS `graduation_results` (
  `id` CHAR(36) NOT NULL,
  `student_id` CHAR(36) NOT NULL,
  `condition_id` CHAR(36) NOT NULL,
  `gpa` DECIMAL(3,2) NULL,
  `total_credits` INT NULL,
  `failed_credits` INT NULL,
  `result` SMALLINT NULL,
  `classification` SMALLINT NULL,
  `decision_date` DATE NULL,
  `reviewer` CHAR(36) NULL,
  `note` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NULL,
  `created_by` CHAR(36) NULL,
  `updated_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  `deleted_by` CHAR(36) NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `idx_grad_results_condition` (`condition_id`),
  KEY `idx_grad_results_student` (`student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Kết quả tốt nghiệp nhóm 11';

-- 5.4. Hồ sơ đề nghị xét tốt nghiệp (graduation_profiles)
CREATE TABLE IF NOT EXISTS `graduation_profiles` (
  `id` CHAR(36) NOT NULL,
  `profile_code` VARCHAR(50) NOT NULL,
  `student_id` CHAR(36) NOT NULL,
  `session_id` CHAR(36) NULL,
  `status` VARCHAR(30) NOT NULL,
  `submitted_date` DATETIME NULL,
  `review_date` DATETIME NULL,
  `reviewer_id` CHAR(36) NULL,
  `note` VARCHAR(500) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NULL,
  `created_by` CHAR(36) NULL,
  `updated_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  `deleted_by` CHAR(36) NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_graduation_profiles_profile_code` (`profile_code`),
  KEY `idx_grad_profiles_student` (`student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Hồ sơ tốt nghiệp nhóm 11';

